conceptExample.sql:
SELECT managerId, SUM(salary) AS team_salary
FROM Employee
GROUP BY managerId;

lessons.solution:
SELECT e.name AS employee_name, m.name AS manager_name
FROM Employee AS e
JOIN Employee AS m ON e.managerId = m.id;

conceptExample.sql:
WITH high_salary AS (
  SELECT name, salary
  FROM Employee
  WHERE salary >= 90
)
SELECT name FROM high_salary;

SELECT h.name
FROM (
  SELECT name, salary
  FROM Employee
  WHERE salary >= 90
) AS h;

SELECT name
FROM Employee
WHERE salary = (SELECT MAX(salary) FROM Employee);

lessons.solution:
SELECT name, salary
FROM Employee
WHERE salary > (SELECT AVG(salary) FROM Employee);

conceptExample.sql:
SELECT c.artist_name
FROM concerts AS c
WHERE EXISTS (
  SELECT 1 FROM concerts AS peer
  WHERE peer.genre = c.genre AND peer.artist_id <> c.artist_id
);

WITH RECURSIVE steps(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM steps WHERE n < 3
)
SELECT n FROM steps;

lessons.solution:
SELECT sale_id, shop, amount,
       SUM(amount) OVER (PARTITION BY shop) AS shop_total
FROM sales;

conceptExample.sql:
SELECT sale_id, amount,
       SUM(amount) OVER (
         ORDER BY sale_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS running_total
FROM sales;

lessons.solution:
SELECT sale_id, shop,
       SUM(amount) OVER (
         PARTITION BY shop ORDER BY sale_date, sale_id
         ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS running_total
FROM sales;

conceptExample.sql:
WITH numbered AS (
  SELECT artist_name, genre,
         ROW_NUMBER() OVER (PARTITION BY genre ORDER BY artist_id) AS rn
  FROM concerts
)
SELECT artist_name, genre FROM numbered WHERE rn = 1;

SELECT sale_id, amount,
       LAG(amount) OVER (ORDER BY sale_id) AS previous_amount
FROM sales;

